//! The systemd user unit.
//!
//! Generated by the daemon that will be run by it, so the `ExecStart` path is
//! always the binary you installed rather than something a GUI guessed at.
//!
//! Four differences from the unit the old GUI wrote, each one a fix:
//!
//! * **No `network-online.target`.** That is a *system* unit; referencing it
//!   from a *user* unit is silently inert — verified on this machine, where
//!   `systemctl --user list-unit-files` has no such unit. The old unit therefore
//!   did not actually wait for the network, which is what let the daemon start
//!   before it was up. Readiness is decided at runtime from NetworkManager over
//!   D-Bus instead (P1).
//! * **`Type=notify` + `WatchdogSec`.** A daemon wedged on a hung FUSE mount
//!   stops pinging and gets restarted, instead of sitting there "active" doing
//!   nothing forever.
//! * **`Restart=always`, `StartLimitIntervalSec=0`.** `on-failure` never
//!   restarted after a clean exit, and the default start limiter could give up
//!   entirely.
//! * **No `Environment=RUST_LOG=info`.** The old unit set it while the code
//!   built its filter with `EnvFilter::try_new`, which ignores the environment —
//!   so it did nothing. Level comes from the config; `RUST_LOG` still works as
//!   an override because we now read it.

use std::path::Path;

pub const UNIT_NAME: &str = "onedrive-rcd.service";

/// Render the unit for a daemon installed at `binary`.
pub fn render(binary: &Path) -> String {
    format!(
        "\
[Unit]
Description=OneDrive daemon
Documentation=https://github.com/Yolo-TM/onedrive-mount
# Deliberately no After=network-online.target: that is a system unit and has no
# effect here. Network readiness is handled at runtime over D-Bus.

[Service]
Type=notify
NotifyAccess=main
ExecStart={exec}
Restart=always
RestartSec=2
# Never stop trying to restart; the daemon is useless if it gives up.
StartLimitIntervalSec=0
# A wedged daemon stops pinging and gets restarted rather than hanging forever.
WatchdogSec=60
TimeoutStopSec=30
Environment=RUST_BACKTRACE=1

[Install]
WantedBy=default.target
",
        exec = binary.display()
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn renders_the_documented_unit() {
        let unit = render(Path::new("/home/t/.nix-profile/bin/onedrive-rcd"));

        assert!(unit.contains("ExecStart=/home/t/.nix-profile/bin/onedrive-rcd"));
        assert!(unit.contains("Type=notify"));
        assert!(unit.contains("NotifyAccess=main"));
        assert!(unit.contains("WatchdogSec=60"));
        assert!(unit.contains("Restart=always"));
        assert!(unit.contains("StartLimitIntervalSec=0"));
        assert!(unit.contains("WantedBy=default.target"));
    }

    /// Regression guards for the specific mistakes in the old unit.
    #[test]
    fn does_not_repeat_the_old_units_mistakes() {
        let unit = render(Path::new("/usr/bin/onedrive-rcd"));

        assert!(
            !unit.contains("network-online.target\n"),
            "a user unit cannot order against a system target"
        );
        assert!(!unit.contains("NetworkManager-wait-online"), "same problem");
        assert!(
            !unit.contains("Restart=on-failure"),
            "a clean exit must also restart"
        );
        assert!(
            !unit.contains("RUST_LOG="),
            "the log level comes from the config"
        );
    }

    #[test]
    fn is_a_single_trailing_newline_terminated_file() {
        let unit = render(Path::new("/usr/bin/onedrive-rcd"));
        assert!(unit.ends_with("default.target\n"));
        assert!(!unit.ends_with("\n\n"));
    }
}
